function useCatalog() {
  const [catalog, setCatalog] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(CATALOG_KEY, true);
        if (res && res.value) {
          setCatalog(JSON.parse(res.value));
        } else {
          await window.storage.set(CATALOG_KEY, JSON.stringify(SEED), true);
          setCatalog(SEED);
        }
      } catch (e) {
        setCatalog(SEED);
      }
      setLoading(false);
    })();
  }, []);

  const persist = async (next) => {
    setCatalog(next);
    try {
      await window.storage.set(CATALOG_KEY, JSON.stringify(next), true);
    } catch (e) {
      console.error("Catalog save failed", e);
    }
  };

  return { catalog, setCatalog: persist, loading };
}

export default function ShoelineApp() {
  const { catalog, setCatalog, loading } = useCatalog();
  const [view, setView] = useState("catalog"); // catalog | admin
  const [customerName, setCustomerName] = useState("");
  const [order, setOrder] = useState({});
  const [activeArticle, setActiveArticle] = useState(null);
  const [orderOpen, setOrderOpen] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [search, setSearch] = useState("");
  const [adminPromptOpen, setAdminPromptOpen] = useState(false);
  const [passInput, setPassInput] = useState("");
  const [passError, setPassError] = useState(false);

  const addLine = (article, color, qty) => {
    const key = `${article.id}-${color}`;
    setOrder((o) => ({
      ...o,
      [key]: { article: article.id, color, qty: (o[key]?.qty || 0) + qty, retail: article.retail },
    }));
  };

  const removeLine = (key) => {
    setOrder((o) => {
      const next = { ...o };
      delete next[key];
      return next;
    });
  };

  const lines = useMemo(() => Object.entries(order).map(([key, v]) => ({ key, ...v })), [order]);
  const totalQty = lines.reduce((s, l) => s + l.qty, 0);
  const totalValue = lines.reduce((s, l) => s + l.qty * (l.retail || 0), 0);

  const filteredCatalog = useMemo(() => {
    if (!catalog) return [];
    const q = search.trim().toLowerCase();
    if (!q) return catalog;
    return catalog.filter((a) => a.id.toLowerCase().includes(q));
  }, [catalog, search]);

  const [submitError, setSubmitError] = useState(null);
  const [fallbackText, setFallbackText] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  const buildOrderText = (payload) => {
    const itemLines = payload.lines.map((l) => `${l.article} · ${l.color} · ${l.qty / 12} carton (${l.qty} pairs)`).join("\n");
    return `Shoeline Order\nName: ${payload.customerName}\n\n${itemLines}\n\nTotal pairs: ${payload.totalQty}\nTotal value: Rs ${payload.totalValue.toLocaleString()}`;
  };

  const submitOrder = async () => {
    const payload = {
      customerName,
      submittedAt: new Date().toISOString(),
      lines: lines.map((l) => ({ article: l.article, color: l.color, qty: l.qty, retail: l.retail })),
      totalQty,
      totalValue,
    };
    setSubmitError(null);
    setFallbackText(null);
    setSubmitting(true);

    const attemptSave = async () => {
      // Apps Script web apps don't return CORS headers for POST, so the
      // response body can't be read from the browser — "no-cors" avoids
      // that failing the request; a genuine network/offline error still throws.
      await fetch(ORDERS_ENDPOINT, {
        method: "POST",
        mode: "no-cors",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify(payload),
      });
      return true;
    };

    try {
      let ok = await attemptSave().catch(() => false);
      if (!ok) {
        // brief pause then one retry — weak/spotty signal is often transient
        await new Promise((r) => setTimeout(r, 800));
        ok = await attemptSave().catch(() => false);
      }
      if (ok) {
        setSubmitted(true);
      } else {
        setFallbackText(buildOrderText(payload));
      }
    } catch (e) {
      setFallbackText(buildOrderText(payload));
    }
    setSubmitting(false);
  };

  const openAdmin = () => {
    if (view === "admin") {
      setView("catalog");
    } else {
      setAdminPromptOpen(true);
    }
  };

  const checkPasscode = () => {
    if (passInput === ADMIN_PASSCODE) {
      setView("admin");
      setAdminPromptOpen(false);
      setPassInput("");
      setPassError(false);
    } else {
      setPassError(true);
    }
  };

  if (loading || !catalog) {
    return (
      <div style={{ minHeight: "100vh", background: "#141414", color: "#EDEAE3", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "system-ui" }}>
        Loading catalog…
      </div>
    );
  }

  return (
    <div style={{ fontFamily: "'Inter', system-ui, sans-serif", background: "#141414", minHeight: "100vh", color: "#EDEAE3" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Fraunces:wght@600;700&display=swap');
        * { box-sizing: border-box; }
        .pop { animation: pop 0.5s ease; }
        @keyframes pop { 0%{transform:scale(0.85);opacity:0} 100%{transform:scale(1);opacity:1} }
        .sheet { animation: sheet 0.25s ease-out; }
        @keyframes sheet { from{transform:translateY(100%)} to{transform:translateY(0)} }
        button:focus-visible { outline: 3px solid #C9A15A; outline-offset: 2px; }
        input:focus-visible, textarea:focus-visible { outline: 2px solid #C9A15A; }
        ::-webkit-scrollbar { width: 6px; }
        @media (prefers-reduced-motion: reduce) { .pop, .sheet { animation: none !important; } }
      `}</style>

      {view === "catalog" ? (
        <CatalogView
          catalog={filteredCatalog}
          search={search}
          setSearch={setSearch}
          customerName={customerName}
          setCustomerName={setCustomerName}
          setActiveArticle={setActiveArticle}
          totalQty={totalQty}
          totalValue={totalValue}
          orderOpen={orderOpen}
          setOrderOpen={setOrderOpen}
          onAdminTap={openAdmin}
        />
      ) : (
        <AdminView catalog={catalog} setCatalog={setCatalog} onBack={() => setView("catalog")} />
      )}

      {activeArticle && (
        <ColorQtySheet article={activeArticle} onClose={() => setActiveArticle(null)} onAdd={addLine} />
      )}

      {orderOpen && (
        <OrderSheet
          lines={lines}
          totalQty={totalQty}
          totalValue={totalValue}
          customerName={customerName}
          submitted={submitted}
          submitError={submitError}
          fallbackText={fallbackText}
          submitting={submitting}
          onClose={() => setOrderOpen(false)}
          onRemove={removeLine}
          onSubmit={submitOrder}
        />
      )}

      {adminPromptOpen && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.65)", zIndex: 40, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }} onClick={() => setAdminPromptOpen(false)}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#1E1E1E", borderRadius: 16, padding: 22, width: "100%", maxWidth: 300, border: "1px solid #2A2A2A" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
              <Lock size={18} color="#C9A15A" />
              <h3 style={{ fontFamily: "'Fraunces', serif", fontSize: 16, margin: 0 }}>Admin Passcode</h3>
            </div>
            <input
              type="password"
              value={passInput}
              onChange={(e) => { setPassInput(e.target.value); setPassError(false); }}
              onKeyDown={(e) => e.key === "Enter" && checkPasscode()}
              placeholder="****"
              style={{ width: "100%", background: "#141414", border: `1px solid ${passError ? "#C1440E" : "#2A2A2A"}`, borderRadius: 10, padding: 10, color: "#EDEAE3", fontSize: 14, marginBottom: 10 }}
            />
            {passError && <p style={{ color: "#C1440E", fontSize: 12, marginBottom: 10 }}>Galat passcode</p>}
            <button onClick={checkPasscode} style={{ width: "100%", background: "#C9A15A", color: "#141414", border: "none", borderRadius: 10, padding: 11, fontWeight: 700, cursor: "pointer" }}>
              Enter
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- Customer catalog view ---------------- */

function CatalogView({ catalog, search, setSearch, customerName, setCustomerName, setActiveArticle, totalQty, totalValue, orderOpen, setOrderOpen, onAdminTap }) {
  return (
    <>
      <header style={{ padding: "20px 16px 16px", borderBottom: "1px solid #2A2A2A" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div>
            <p style={{ color: "#C9A15A", fontSize: 11, letterSpacing: 3, textTransform: "uppercase", margin: 0, fontWeight: 600 }}>
              New Arrivals
            </p>
            <h1 style={{ fontFamily: "'Fraunces', serif", fontSize: 26, fontWeight: 700, margin: "4px 0 10px" }}>
              Shoeline
            </h1>
          </div>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8, background: "#1E1E1E", borderRadius: 12, padding: "10px 12px", border: "1px solid #2A2A2A", marginBottom: 10 }}>
          <User size={16} color="#C9A15A" />
          <input
            value={customerName}
            onChange={(e) => setCustomerName(e.target.value)}
            placeholder="Apna naam likhein"
            style={{ background: "transparent", border: "none", color: "#EDEAE3", fontSize: 14, flex: 1, outline: "none" }}
          />
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8, background: "#1E1E1E", borderRadius: 12, padding: "10px 12px", border: "1px solid #2A2A2A" }}>
          <Search size={16} color="#8A8578" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Article code search karein"
            style={{ background: "transparent", border: "none", color: "#EDEAE3", fontSize: 14, flex: 1, outline: "none" }}
          />
        </div>
      </header>

      <main style={{ padding: "16px 12px 110px", display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
        {catalog.map((a) => (
          <button
            key={a.id}
            onClick={() => setActiveArticle(a)}
            style={{ background: "#1E1E1E", border: "1px solid #2A2A2A", borderRadius: 16, padding: 10, textAlign: "left", cursor: "pointer", color: "#EDEAE3" }}
          >
            <div style={{ width: "100%", aspectRatio: "1", borderRadius: 10, overflow: "hidden", background: "#141414", marginBottom: 8, display: "flex", alignItems: "center", justifyContent: "center" }}>
              {a.image ? (
                <img src={a.image} alt={a.id} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              ) : (
                <span style={{ fontSize: 28 }}>👞</span>
              )}
            </div>
            <p style={{ fontSize: 10, color: "#8A8578", letterSpacing: 1, margin: 0 }}>{a.id}</p>
            <p style={{ fontSize: 11, color: "#8A8578", margin: "2px 0 4px" }}>{a.size || "Size N/A"}</p>
            <p style={{ fontSize: 13, color: "#C9A15A", fontWeight: 700, margin: 0 }}>
              {a.retail ? `Rs ${a.retail.toLocaleString()}` : "Price N/A"}
            </p>
          </button>
        ))}
        {catalog.length === 0 && (
          <p style={{ gridColumn: "1 / -1", textAlign: "center", color: "#8A8578", marginTop: 40 }}>Koi article nahi mila.</p>
        )}
      </main>

      {totalQty > 0 && !orderOpen && (
        <button
          onClick={() => setOrderOpen(true)}
          style={{ position: "fixed", bottom: 16, left: 16, right: 16, background: "#C9A15A", border: "none", borderRadius: 16, padding: "14px 18px", display: "flex", justifyContent: "space-between", alignItems: "center", color: "#141414", cursor: "pointer", boxShadow: "0 8px 24px rgba(0,0,0,0.5)" }}
        >
          <span style={{ fontSize: 13, fontWeight: 700 }}>{totalQty} pairs selected</span>
          <span style={{ fontSize: 13, fontWeight: 700, display: "flex", alignItems: "center", gap: 6 }}>
            <ClipboardList size={16} /> Order dekhein
          </span>
        </button>
      )}

      <button
        onClick={onAdminTap}
        style={{ position: "fixed", bottom: 8, right: 8, background: "transparent", border: "none", color: "#3A3A3A", padding: 8, cursor: "pointer" }}
        aria-label="Admin"
      >
        <Settings size={16} />
      </button>
    </>
  );
}

/* ---------------- Color + carton selection sheet ---------------- */

function ColorQtySheet({ article, onClose, onAdd }) {
  const [cartons, setCartons] = useState(() => Object.fromEntries(article.colors.map((c) => [c, 0])));

  const setCartonFor = (color, delta) => {
    setCartons((prev) => ({ ...prev, [color]: Math.max(0, prev[color] + delta) }));
  };

  const totalCartons = Object.values(cartons).reduce((s, n) => s + n, 0);
  const totalPairs = totalCartons * CARTON;

  const handleAdd = () => {
    Object.entries(cartons).forEach(([color, n]) => {
      if (n > 0) onAdd(article, color, n * CARTON);
    });
    onClose();
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", zIndex: 20 }} onClick={onClose}>
      <div className="sheet" onClick={(e) => e.stopPropagation()} style={{ position: "absolute", bottom: 0, left: 0, right: 0, background: "#1E1E1E", borderRadius: "20px 20px 0 0", padding: 20, maxHeight: "85vh", overflowY: "auto" }}>
        <div style={{ display: "flex", gap: 14, marginBottom: 16 }}>
          <div style={{ width: 72, height: 72, borderRadius: 12, overflow: "hidden", background: "#141414", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
            {article.image ? <img src={article.image} alt={article.id} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <span style={{ fontSize: 30 }}>👞</span>}
          </div>
          <div>
            <p style={{ fontSize: 10, color: "#8A8578", margin: 0 }}>{article.id} · {article.size || "Size N/A"}</p>
            <h3 style={{ fontFamily: "'Fraunces', serif", fontSize: 17, margin: "2px 0 4px" }}>{article.id}</h3>
            <p style={{ fontSize: 13, color: "#C9A15A", fontWeight: 700, margin: 0 }}>{article.retail ? `Rs ${article.retail.toLocaleString()} / pair` : "Price N/A"}</p>
          </div>
        </div>

        <p style={{ fontSize: 11, color: "#8A8578", marginBottom: 14 }}>
          1 carton = {CARTON} pairs (same color). Jitne colors chahiye, har ek ke cartons alag se badhayein.
        </p>

        <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 20 }}>
          {article.colors.map((c) => (
            <div key={c} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", background: "#141414", border: "1px solid #2A2A2A", borderRadius: 12, padding: "10px 12px" }}>
              <div>
                <p style={{ fontSize: 14, fontWeight: 600, margin: 0 }}>{c}</p>
                <p style={{ fontSize: 11, color: "#8A8578", margin: "2px 0 0" }}>
                  {cartons[c] > 0 ? `${cartons[c]} carton${cartons[c] > 1 ? "s" : ""} · ${cartons[c] * CARTON} pairs` : "Nahi liya"}
                </p>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <button onClick={() => setCartonFor(c, -1)} style={{ width: 32, height: 32, borderRadius: 9, border: "1px solid #2A2A2A", background: "#1E1E1E", color: "#EDEAE3", cursor: "pointer" }}>
                  <Minus size={14} style={{ margin: "auto" }} />
                </button>
                <span style={{ fontSize: 15, fontWeight: 700, minWidth: 16, textAlign: "center" }}>{cartons[c]}</span>
                <button onClick={() => setCartonFor(c, 1)} style={{ width: 32, height: 32, borderRadius: 9, border: "1px solid #2A2A2A", background: "#1E1E1E", color: "#EDEAE3", cursor: "pointer" }}>
                  <Plus size={14} style={{ margin: "auto" }} />
                </button>
              </div>
            </div>
          ))}
        </div>

        {totalCartons > 0 && (
          <p style={{ fontSize: 12, color: "#8A8578", marginBottom: 12, textAlign: "center" }}>
            Total: {totalCartons} carton{totalCartons > 1 ? "s" : ""} · {totalPairs} pairs
          </p>
        )}

        <button
          disabled={totalCartons === 0}
          onClick={handleAdd}
          style={{ width: "100%", background: totalCartons === 0 ? "#3A3A3A" : "#C9A15A", color: "#141414", border: "none", borderRadius: 12, padding: 13, fontSize: 14, fontWeight: 700, cursor: totalCartons === 0 ? "not-allowed" : "pointer" }}
        >
          Order Sheet Mein Daalein
        </button>
      </div>
    </div>
  );
}

/* ---------------- Order summary sheet ---------------- */

function OrderSheet({ lines, totalQty, totalValue, customerName, submitted, submitError, fallbackText, submitting, onClose, onRemove, onSubmit }) {
  const [copied, setCopied] = useState(false);
  const textareaRef = useRef(null);

  const copyFallback = () => {
    const ta = textareaRef.current;
    if (!ta) return;
    ta.focus();
    ta.select();
    ta.setSelectionRange(0, ta.value.length);
    let ok = false;
    try {
      ok = document.execCommand("copy");
    } catch (e) {
      ok = false;
    }
    if (ok) {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } else if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(fallbackText).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      }).catch(() => {});
    }
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", zIndex: 10 }} onClick={onClose}>
      <div className="sheet" onClick={(e) => e.stopPropagation()} style={{ position: "absolute", bottom: 0, left: 0, right: 0, maxHeight: "85vh", overflowY: "auto", background: "#1E1E1E", borderRadius: "20px 20px 0 0", padding: 18 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <h2 style={{ fontFamily: "'Fraunces', serif", fontSize: 19, fontWeight: 700, margin: 0 }}>Order Sheet</h2>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer" }}>
            <X size={22} color="#EDEAE3" />
          </button>
        </div>

        {!submitted ? (
          <>
            <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 16 }}>
              {lines.map((l) => (
                <div key={l.key} style={{ display: "flex", alignItems: "center", gap: 10, background: "#141414", borderRadius: 12, padding: 10, border: "1px solid #2A2A2A" }}>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontSize: 13, fontWeight: 600, margin: 0 }}>{l.article} <span style={{ color: "#8A8578", fontWeight: 400 }}>· {l.color}</span></p>
                    <p style={{ fontSize: 12, color: "#8A8578", margin: "2px 0 0" }}>{l.qty / 12} carton{l.qty / 12 > 1 ? "s" : ""} ({l.qty} pairs){l.retail ? ` · Rs ${l.retail.toLocaleString()}/pair` : ""}</p>
                  </div>
                  <button onClick={() => onRemove(l.key)} style={{ background: "none", border: "none", color: "#8A8578", cursor: "pointer" }}>
                    <X size={16} />
                  </button>
                </div>
              ))}
            </div>
            <div style={{ borderTop: "1px solid #2A2A2A", paddingTop: 12, marginBottom: 14 }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                <span style={{ fontSize: 13, color: "#8A8578" }}>Total pairs</span>
                <span style={{ fontSize: 13, fontWeight: 600 }}>{totalQty}</span>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <span style={{ fontSize: 13, color: "#8A8578" }}>Total value</span>
                <span style={{ fontSize: 16, fontWeight: 700, color: "#C9A15A" }}>Rs {totalValue.toLocaleString()}</span>
              </div>
            </div>
            <button
              disabled={!customerName || lines.length === 0 || submitting}
              onClick={onSubmit}
              style={{ width: "100%", background: !customerName || lines.length === 0 || submitting ? "#3A3A3A" : "#C9A15A", color: "#141414", border: "none", borderRadius: 12, padding: 13, fontSize: 14, fontWeight: 700, cursor: !customerName || lines.length === 0 || submitting ? "not-allowed" : "pointer" }}
            >
              {submitting ? "Save ho raha hai…" : "Order Confirm Karein"}
            </button>
            {!customerName && <p style={{ fontSize: 11, color: "#8A8578", textAlign: "center", marginTop: 8 }}>Pehle apna naam upar likhein</p>}
            {submitError && <p style={{ fontSize: 12, color: "#C1440E", textAlign: "center", marginTop: 8 }}>{submitError}</p>}

            {fallbackText && (
              <div style={{ marginTop: 16, background: "#141414", border: "1px solid #C1440E", borderRadius: 12, padding: 14 }}>
                <p style={{ fontSize: 12, color: "#C1440E", fontWeight: 600, marginBottom: 8 }}>
                  Order online save nahi ho saka (is preview mein hi — real hosting par ye masla nahi hoga). Neeche box ko tap karke hold karein, "Select All" dabayein, phir apne phone ke normal "Copy" option se copy kar lein:
                </p>
                <textarea
                  ref={textareaRef}
                  readOnly
                  value={fallbackText}
                  onFocus={(e) => e.target.select()}
                  style={{ width: "100%", minHeight: 140, whiteSpace: "pre-wrap", fontSize: 12, color: "#EDEAE3", fontFamily: "inherit", background: "#0E0E0E", border: "1px solid #2A2A2A", borderRadius: 8, padding: 10, margin: 0, marginBottom: 10, resize: "vertical", boxSizing: "border-box" }}
                />
                <button onClick={copyFallback} style={{ width: "100%", background: "#C9A15A", color: "#141414", border: "none", borderRadius: 10, padding: 10, fontSize: 13, fontWeight: 700, cursor: "pointer" }}>
                  {copied ? "Copy ho gaya ✓" : "Copy Karein"}
                </button>
              </div>
            )}
          </>
        ) : (
          <div className="pop" style={{ textAlign: "center", padding: "20px 0" }}>
            <div style={{ width: 56, height: 56, borderRadius: "50%", background: "#C9A15A22", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 14px" }}>
              <Check size={28} color="#C9A15A" />
            </div>
            <h3 style={{ fontFamily: "'Fraunces', serif", fontSize: 18, margin: "0 0 6px" }}>Order Save Ho Gaya</h3>
            <p style={{ fontSize: 13, color: "#8A8578", marginBottom: 18 }}>
              {customerName} · {totalQty} pairs · Rs {totalValue.toLocaleString()}
            </p>
            <p style={{ fontSize: 12, color: "#8A8578" }}>
              Connection na ho toh order phone mein safe hai — signal aate hi khud sync ho jayega.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

/* ---------------- Admin view ---------------- */

function AdminView({ catalog, setCatalog, onBack }) {
  const [tab, setTab] = useState("articles"); // articles | orders
  const [editing, setEditing] = useState(null); // article being edited, or "new"
  const [search, setSearch] = useState("");

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return catalog;
    return catalog.filter((a) => a.id.toLowerCase().includes(q));
  }, [catalog, search]);

  const saveArticle = (updated, originalId) => {
    let next;
    if (originalId) {
      next = catalog.map((a) => (a.id === originalId ? updated : a));
    } else {
      next = [updated, ...catalog];
    }
    setCatalog(next);
    setEditing(null);
  };

  const [pendingDelete, setPendingDelete] = useState(null);

  const deleteArticle = (id) => {
    setCatalog(catalog.filter((a) => a.id !== id));
    setPendingDelete(null);
  };

  return (
    <div style={{ paddingBottom: 40 }}>
      <header style={{ padding: "18px 16px 0", borderBottom: "1px solid #2A2A2A" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <button onClick={onBack} style={{ background: "none", border: "none", color: "#EDEAE3", cursor: "pointer" }}>
              <ArrowLeft size={20} />
            </button>
            <h1 style={{ fontFamily: "'Fraunces', serif", fontSize: 19, fontWeight: 700, margin: 0 }}>Admin Panel</h1>
          </div>
          {tab === "articles" && (
            <button onClick={() => setEditing("new")} style={{ background: "#C9A15A", border: "none", borderRadius: 10, padding: "8px 10px", display: "flex", alignItems: "center", gap: 6, color: "#141414", fontWeight: 700, fontSize: 12, cursor: "pointer" }}>
              <PackagePlus size={14} /> Naya
            </button>
          )}
        </div>
        <div style={{ display: "flex", gap: 6, marginBottom: 0 }}>
          <button
            onClick={() => setTab("articles")}
            style={{ flex: 1, background: "none", border: "none", borderBottom: tab === "articles" ? "2px solid #C9A15A" : "2px solid transparent", color: tab === "articles" ? "#C9A15A" : "#8A8578", fontWeight: 600, fontSize: 13, padding: "8px 4px", cursor: "pointer" }}
          >
            Articles
          </button>
          <button
            onClick={() => setTab("orders")}
            style={{ flex: 1, background: "none", border: "none", borderBottom: tab === "orders" ? "2px solid #C9A15A" : "2px solid transparent", color: tab === "orders" ? "#C9A15A" : "#8A8578", fontWeight: 600, fontSize: 13, padding: "8px 4px", cursor: "pointer" }}
          >
            Orders
          </button>
        </div>
      </header>

      {tab === "orders" ? (
        <OrdersTab />
      ) : (
      <div style={{ padding: "14px 16px" }}>
        <p style={{ fontSize: 11, color: "#8A8578", marginBottom: 12 }}>
          Orders dekhne aur Excel/PDF export ke liye "Orders" tab par jaayein.
        </p>

        <div style={{ display: "flex", alignItems: "center", gap: 8, background: "#1E1E1E", borderRadius: 12, padding: "10px 12px", border: "1px solid #2A2A2A", marginBottom: 14 }}>
          <Search size={16} color="#8A8578" />
          <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Article search karein" style={{ background: "transparent", border: "none", color: "#EDEAE3", fontSize: 14, flex: 1, outline: "none" }} />
        </div>

        <p style={{ fontSize: 12, color: "#8A8578", marginBottom: 10 }}>{catalog.length} articles total</p>

        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {filtered.map((a) => (
            <div key={a.id} style={{ display: "flex", alignItems: "center", gap: 10, background: "#1E1E1E", border: "1px solid #2A2A2A", borderRadius: 12, padding: 10 }}>
              <div style={{ width: 46, height: 46, borderRadius: 8, overflow: "hidden", background: "#141414", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                {a.image ? <img src={a.image} alt={a.id} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <span>👞</span>}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <p style={{ fontSize: 13, fontWeight: 600, margin: 0 }}>{a.id}</p>
                <p style={{ fontSize: 11, color: "#8A8578", margin: "2px 0 0", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                  {a.colors.join(", ")} · {a.size || "size?"} · {a.retail ? `Rs ${a.retail}` : "price?"}
                </p>
              </div>
              <button onClick={() => setEditing(a)} style={{ background: "none", border: "none", color: "#C9A15A", cursor: "pointer", padding: 6 }}>
                <Pencil size={16} />
              </button>
              <button onClick={() => setPendingDelete(a.id)} style={{ background: "none", border: "none", color: "#C1440E", cursor: "pointer", padding: 6 }}>
                <Trash2 size={16} />
              </button>
            </div>
          ))}
        </div>
      </div>
      )}

      {editing && (
        <EditArticleModal
          article={editing === "new" ? null : editing}
          existingIds={catalog.map((a) => a.id)}
          onClose={() => setEditing(null)}
          onSave={saveArticle}
        />
      )}

      {pendingDelete && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.65)", zIndex: 40, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }} onClick={() => setPendingDelete(null)}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#1E1E1E", borderRadius: 16, padding: 20, width: "100%", maxWidth: 300, border: "1px solid #2A2A2A" }}>
            <p style={{ fontSize: 14, marginBottom: 16 }}><strong>{pendingDelete}</strong> ko hatana hai?</p>
            <div style={{ display: "flex", gap: 10 }}>
              <button onClick={() => setPendingDelete(null)} style={{ flex: 1, background: "#141414", border: "1px solid #2A2A2A", borderRadius: 10, padding: 11, color: "#EDEAE3", cursor: "pointer" }}>Cancel</button>
              <button onClick={() => deleteArticle(pendingDelete)} style={{ flex: 1, background: "#C1440E", border: "none", borderRadius: 10, padding: 11, color: "#fff", fontWeight: 700, cursor: "pointer" }}>Hatayein</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function OrdersTab() {
  const [loading, setLoading] = useState(true);
  const [rows, setRows] = useState([]);
  const [loadError, setLoadError] = useState(null);
  const [exportUrl, setExportUrl] = useState(null);
  const [exportName, setExportName] = useState("");
  const [exportError, setExportError] = useState(null);

  const loadOrders = async () => {
    setLoading(true);
    setLoadError(null);
    setExportUrl(null);
    try {
      const res = await fetch(ORDERS_ENDPOINT, { method: "GET" });
      const data = await res.json();
      setRows(Array.isArray(data) ? data : []);
    } catch (e) {
      setLoadError("Orders load nahi ho sake — internet check karein. (" + (e && e.message ? e.message : String(e)) + ")");
    }
    setLoading(false);
  };

  useEffect(() => {
    loadOrders();
  }, []);

  const byCustomer = useMemo(() => {
    const map = {};
    rows.forEach((r) => {
      const name = r["Customer Name"] || "Naam nahi diya";
      if (!map[name]) map[name] = [];
      map[name].push(r);
    });
    return map;
  }, [rows]);

  const totalPairs = rows.reduce((s, r) => s + (Number(r["Quantity (pairs)"]) || 0), 0);
  const totalValue = rows.reduce((s, r) => s + (Number(r["Line Total"]) || 0), 0);

  const exportExcel = () => {
    setExportError(null);
    try {
      const safeRows = rows.length > 0 ? rows : [{ "Customer Name": "", "Article": "", "Color": "", "Quantity (pairs)": "", "Cartons": "", "Retail (per pair)": "", "Line Total": "", "Submitted At": "" }];
      const ws = XLSX.utils.json_to_sheet(safeRows);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Orders");
      const arrayBuffer = XLSX.write(wb, { bookType: "xlsx", type: "array" });
      const blob = new Blob([arrayBuffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
      const url = URL.createObjectURL(blob);
      setExportUrl(url);
      setExportName(`Shoeline_Orders_${new Date().toISOString().slice(0, 10)}.xlsx`);
    } catch (e) {
      setExportError("Excel export mein masla hua: " + (e && e.message ? e.message : String(e)));
    }
  };

  const printPdf = () => {
    window.print();
  };

  return (
    <div style={{ padding: "14px 16px" }}>
      <style>{`
        @media print {
          body * { visibility: hidden; }
          #print-orders, #print-orders * { visibility: visible; }
          #print-orders { position: absolute; top: 0; left: 0; width: 100%; padding: 20px; background: #fff !important; color: #111 !important; }
          #print-orders .po-card { border: 1px solid #ccc !important; break-inside: avoid; }
        }
      `}</style>

      <p style={{ fontSize: 11, color: "#8A8578", marginBottom: 12 }}>
        Ye data seedha aapki Google Sheet se aa raha hai — Sheet khud bhi khol kar dekh sakte hain.
      </p>

      <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
        <button onClick={loadOrders} style={{ flex: 1, background: "#1E1E1E", border: "1px solid #2A2A2A", borderRadius: 10, padding: 10, color: "#EDEAE3", fontSize: 12, cursor: "pointer" }}>
          Refresh
        </button>
        <button onClick={printPdf} disabled={rows.length === 0} style={{ flex: 1, background: "#1E1E1E", border: "1px solid #C9A15A", borderRadius: 10, padding: 10, color: "#C9A15A", fontSize: 12, fontWeight: 700, cursor: rows.length === 0 ? "not-allowed" : "pointer" }}>
          PDF (Print)
        </button>
      </div>

      <button
        onClick={exportExcel}
        disabled={rows.length === 0}
        style={{ width: "100%", background: rows.length === 0 ? "#3A3A3A" : "#C9A15A", border: "none", borderRadius: 12, padding: 13, display: "flex", alignItems: "center", justifyContent: "center", gap: 8, color: "#141414", fontWeight: 700, fontSize: 13, cursor: rows.length === 0 ? "not-allowed" : "pointer", marginBottom: exportUrl ? 8 : 14 }}
      >
        <Download size={16} /> Excel Mein Export Karein
      </button>

      {exportUrl && (
        <a
          href={exportUrl}
          download={exportName}
          style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, width: "100%", background: "#1E1E1E", border: "1px solid #C9A15A", borderRadius: 12, padding: 13, color: "#C9A15A", fontWeight: 700, fontSize: 13, textDecoration: "none", marginBottom: 14, boxSizing: "border-box" }}
        >
          <Check size={16} /> File taiyar hai — Yahan tap karein
        </a>
      )}

      {exportError && <p style={{ fontSize: 12, color: "#C1440E", marginBottom: 14, textAlign: "center" }}>{exportError}</p>}
      {loadError && <p style={{ fontSize: 12, color: "#C1440E", marginBottom: 14, textAlign: "center" }}>{loadError}</p>}

      {loading ? (
        <p style={{ color: "#8A8578", textAlign: "center", marginTop: 30 }}>Orders load ho rahe hain…</p>
      ) : rows.length === 0 ? (
        <p style={{ color: "#8A8578", textAlign: "center", marginTop: 30 }}>Abhi tak koi order submit nahi hua.</p>
      ) : (
        <>
          <p style={{ fontSize: 12, color: "#8A8578", marginBottom: 12 }}>
            {Object.keys(byCustomer).length} customers · {totalPairs} pairs · Rs {totalValue.toLocaleString()}
          </p>
          <div id="print-orders">
            {Object.entries(byCustomer).map(([name, custRows]) => (
              <div key={name} className="po-card" style={{ background: "#1E1E1E", border: "1px solid #2A2A2A", borderRadius: 12, padding: 14, marginBottom: 10 }}>
                <h4 style={{ fontFamily: "'Fraunces', serif", fontSize: 15, margin: "0 0 8px" }}>{name}</h4>
                {custRows.map((r, i) => (
                  <p key={i} style={{ fontSize: 12, margin: "2px 0", color: "#C9C6C0" }}>
                    {r["Article"]} · {r["Color"]} · {r["Cartons"]} carton ({r["Quantity (pairs)"]} pairs){r["Retail (per pair)"] ? ` · Rs ${Number(r["Retail (per pair)"]).toLocaleString()}/pair` : ""}
                  </p>
                ))}
                <p style={{ fontSize: 11, color: "#8A8578", margin: "6px 0 0" }}>
                  Total: {custRows.reduce((s, r) => s + (Number(r["Quantity (pairs)"]) || 0), 0)} pairs · Rs {custRows.reduce((s, r) => s + (Number(r["Line Total"]) || 0), 0).toLocaleString()}
                </p>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}


function EditArticleModal({ article, existingIds, onClose, onSave }) {
  const [id, setId] = useState(article?.id || "");
  const [colors, setColors] = useState(article?.colors?.join(", ") || "");
  const [size, setSize] = useState(article?.size || "");
  const [retail, setRetail] = useState(article?.retail || "");
  const [image, setImage] = useState(article?.image || null);
  const [formError, setFormError] = useState(null);
  const fileRef = useRef(null);

  const handleImage = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setImage(reader.result);
    reader.readAsDataURL(file);
  };

  const handleSave = () => {
    if (!id.trim()) { setFormError("Article code likhein"); return; }
    if (!article && existingIds.includes(id.trim())) { setFormError("Ye code pehle se hai"); return; }
    setFormError(null);
    const updated = {
      id: id.trim(),
      colors: colors.split(",").map((c) => c.trim()).filter(Boolean),
      size: size.trim(),
      retail: retail ? Number(retail) : null,
      image,
    };
    onSave(updated, article?.id || null);
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.65)", zIndex: 30, display: "flex", alignItems: "flex-end" }} onClick={onClose}>
      <div className="sheet" onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxHeight: "90vh", overflowY: "auto", background: "#1E1E1E", borderRadius: "20px 20px 0 0", padding: 20 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <h3 style={{ fontFamily: "'Fraunces', serif", fontSize: 18, margin: 0 }}>{article ? "Article Edit Karein" : "Naya Article"}</h3>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer" }}><X size={20} color="#EDEAE3" /></button>
        </div>

        <div style={{ display: "flex", justifyContent: "center", marginBottom: 16 }}>
          <button onClick={() => fileRef.current?.click()} style={{ width: 100, height: 100, borderRadius: 14, background: "#141414", border: "1px dashed #2A2A2A", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", overflow: "hidden" }}>
            {image ? <img src={image} alt="preview" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <Upload size={22} color="#8A8578" />}
          </button>
          <input ref={fileRef} type="file" accept="image/*" onChange={handleImage} style={{ display: "none" }} />
        </div>

        <Field label="Article Code">
          <input value={id} onChange={(e) => setId(e.target.value)} placeholder="e.g. MCL-06" style={fieldStyle} />
        </Field>
        <Field label="Colors (comma se alag karein)">
          <input value={colors} onChange={(e) => setColors(e.target.value)} placeholder="Black, Brown, Tan" style={fieldStyle} />
        </Field>
        <Field label="Size">
          <input value={size} onChange={(e) => setSize(e.target.value)} placeholder="e.g. 40-45" style={fieldStyle} />
        </Field>
        <Field label="Retail Price (Rs)">
          <input value={retail} onChange={(e) => setRetail(e.target.value.replace(/[^0-9]/g, ""))} placeholder="e.g. 4999" style={fieldStyle} />
        </Field>

        {formError && <p style={{ fontSize: 12, color: "#C1440E", marginBottom: 10 }}>{formError}</p>}

        <button onClick={handleSave} style={{ width: "100%", background: "#C9A15A", color: "#141414", border: "none", borderRadius: 12, padding: 13, fontSize: 14, fontWeight: 700, cursor: "pointer", marginTop: 6 }}>
          Save Karein
        </button>
      </div>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <div style={{ marginBottom: 12 }}>
      <p style={{ fontSize: 11, color: "#8A8578", marginBottom: 6 }}>{label}</p>
      {children}
    </div>
  );
}

const fieldStyle = { width: "100%", background: "#141414", border: "1px solid #2A2A2A", borderRadius: 10, padding: 10, color: "#EDEAE3", fontSize: 14 };
